import { GeneralProblem, d } from './utils';
import { NATIVE_ENGLISH_GRADE_UNITS } from '../../nativeEnglishUnitConfig';

type Entry = [string, string, string, string, string, string, string?];

const toProblems = (entries: Entry[]): GeneralProblem[] => entries.map(([question, answer, a, b, c, hint, audio]) => ({
  question,
  answer,
  options: d(answer, a, b, c),
  hint,
  audioPrompt: audio ? { text: audio, lang: 'en-US', autoPlay: false } : undefined,
}));

const fillToFifty = (problems: GeneralProblem[]): GeneralProblem[] => {
  if (problems.length === 0) return [];
  const result = [...problems];
  while (result.length < 50) {
    const base = problems[result.length % problems.length];
    const round = Math.floor(result.length / problems.length) + 1;
    result.push({
      ...base,
      question: `Review ${round}: ${base.question}`,
    });
  }
  return result;
};

