type Concept = {
  term: string;
  answer: string;
  wrongs: [string, string, string];
  hint: string;
};

const conceptUnit = (title: string, concepts: Concept[]): GeneralProblem[] => toProblems(
  concepts.flatMap((concept): Entry[] => [
    [
      `[${title}] Which answer best explains "${concept.term}"?`,
      concept.answer,
      concept.wrongs[0],
      concept.wrongs[1],
      concept.wrongs[2],
      concept.hint,
      concept.term,
    ],
    [
      `[${title}] Which term matches this idea: ${concept.answer}?`,
      concept.term,
      concept.wrongs[0],
      concept.wrongs[1],
      concept.wrongs[2],
      concept.hint,
      concept.term,
    ],
    [
      `[${title}] In a class discussion, when should you use "${concept.term}"?`,
      concept.answer,
      concept.wrongs[0],
      concept.wrongs[1],
      concept.wrongs[2],
      concept.hint,
      concept.term,
    ],
  ]),
);

const c = (term: string, answer: string, wrongs: [string, string, string], hint: string): Concept => ({
  term,
  answer,
  wrongs,
  hint,
});

