const fallbackConceptsFor = (mode: string): Concept[] => {
  if (mode.includes('NATIVE_JAPANESE')) {
    return [
      c('hiragana', 'the basic Japanese phonetic script for native words and grammar endings', ['a punctuation mark only', 'a number system', 'a map symbol'], 'Hiragana is one of the first scripts learners study.'),
      c('katakana', 'the Japanese phonetic script often used for loanwords and emphasis', ['a math operation', 'a weather tool', 'a story setting'], 'Katakana is common in words like テレビ and コーヒー.'),
      c('kanji', 'characters borrowed from Chinese that often carry meaning', ['only sound marks', 'English capital letters', 'a sentence ending'], 'Kanji can represent ideas and words.'),
      c('particle', 'a small word that marks a word role in a Japanese sentence', ['a type of coin', 'a paragraph title', 'a science model'], 'Particles such as は, を, and に show grammar roles.'),
      c('polite form', 'a respectful everyday style often ending with です or ます', ['a rough command only', 'a map direction', 'a fraction name'], 'Polite forms are useful with teachers and new people.'),
      c('verb stem', 'the base part used to build many Japanese verb forms', ['a kanji radical only', 'an adjective ending', 'a loanword mark'], 'Verb stems help create polite and connected forms.'),
      c('adjective', 'a word that describes a noun or state', ['a word that only marks objects', 'a script name', 'a number line'], 'Japanese adjectives can describe size, color, and feelings.'),
      c('context clue', 'information around a word or phrase that helps you understand meaning', ['a random guess', 'a clock time only', 'a single sound with no sentence'], 'Context is important when reading Japanese with kanji.'),
    ];
  }
  if (mode.includes('SCIENCE')) {
    return [
      c('observation', 'information gathered with senses or tools', ['a random guess', 'a story theme', 'a map direction'], 'Scientists begin with observations.'),
      c('evidence', 'data or facts that support an explanation', ['a personal wish only', 'a spelling rule', 'a page title'], 'Evidence supports scientific claims.'),
      c('model', 'a representation used to explain an object or system', ['the real object always', 'an unrelated opinion', 'a voting method'], 'Models help explain things that are large, small, or complex.'),
      c('system', 'parts that work together as a whole', ['one part by itself only', 'a type of punctuation', 'a fraction answer'], 'Body systems and ecosystems have interacting parts.'),
      c('energy', 'the ability to cause change or do work', ['a map symbol', 'a character trait', 'a sentence ending'], 'Energy can move, heat, light, or change things.'),
      c('matter', 'anything that has mass and takes up space', ['only light', 'only a thought', 'a story setting'], 'Solids, liquids, and gases are matter.'),
      c('ecosystem', 'living and nonliving things interacting in an area', ['a single vocabulary word', 'a type of graph only', 'a government branch'], 'Ecosystems include organisms and environment.'),
      c('cycle', 'a repeating series of changes or events', ['a one-time event only', 'a straight line', 'a claim with evidence'], 'Life cycles and water cycles repeat.'),
    ];
  }
  if (
    mode.includes('DIGITAL')
    || mode.includes('ROUTINES')
    || mode.includes('STUDY_SKILLS')
    || mode.includes('FINANCIAL')
    || mode.includes('ONLINE')
    || mode.includes('MEDIA_BALANCE')
    || mode.includes('CAREER')
  ) {
    return [
      c('digital footprint', 'the trail of information a person leaves when using technology', ['a shoe print only', 'a weather map', 'a math symbol'], 'Online choices can leave records.'),
      c('privacy', 'control over personal information', ['sharing every password', 'a public road', 'a fraction model'], 'Privacy helps keep people safe online.'),
      c('kind communication', 'using respectful words with others', ['insults or threats', 'a map key', 'a science tool'], 'Kind words support healthy communities.'),
      c('routine', 'a regular pattern of actions', ['a random one-time event', 'a government branch', 'a landform'], 'Routines help with health and learning.'),
      c('goal', 'something a person plans to work toward', ['a mistake with no plan', 'a coin name', 'a weather front'], 'Goals make progress easier to track.'),
      c('budget', 'a plan for using money', ['spending with no plan', 'a story setting', 'a grammar mark'], 'Budgets help people make choices.'),
      c('media balance', 'using media in a healthy amount', ['screen time all day', 'never thinking about habits', 'a map scale'], 'Balance protects time for sleep, school, and relationships.'),
      c('career skill', 'an ability that can help in future work', ['a password shared online', 'a random rumor', 'a punctuation mark'], 'Problem solving and communication are career skills.'),
    ];
  }
  if (mode.includes('SOCIAL')) {
    return [
      c('community', 'a group of people who live or work together', ['a type of weather', 'a grammar rule', 'a fraction model'], 'Communities share places, rules, and services.'),
      c('citizenship', 'responsible membership in a community or country', ['a landform', 'a decimal point', 'a sound pattern'], 'Citizens have rights and responsibilities.'),
      c('government', 'a system for making and carrying out rules and laws', ['a natural resource only', 'a story conflict', 'a multiplication fact'], 'Governments provide order and services.'),
      c('economy', 'the way people make, buy, sell, and use goods and services', ['a map key only', 'a science tool', 'a poem line'], 'Economies involve producers and consumers.'),
      c('geography', 'the study of places and Earth features', ['the study of sentence parts', 'the study of fractions', 'a voting method'], 'Geography uses maps and location.'),
      c('primary source', 'a source from the time or person being studied', ['a later summary only', 'a random opinion', 'a math graph'], 'Primary sources are evidence from the past.'),
      c('culture', 'the language, beliefs, customs, arts, and traditions of a group', ['only the weather', 'only a road', 'only a number'], 'Culture shapes how people live.'),
      c('civic responsibility', 'an action that helps a community function well', ['ignoring laws', 'hiding information', 'damaging public spaces'], 'Voting, serving, and following laws are civic responsibilities.'),
    ];
  }
  if (mode.includes('MATH')) {
    return [
      c('equation', 'a math statement with an equals sign', ['a sentence fragment', 'a map symbol', 'a science observation'], 'Equations show equality.'),
      c('strategy', 'a planned way to solve a problem', ['a random guess only', 'a source citation', 'a character trait'], 'Math strategies make work organized.'),
      c('estimate', 'a reasonable close answer', ['an exact quote', 'a story setting', 'a law made by government'], 'Estimates help check reasonableness.'),
      c('pattern', 'a repeated or predictable arrangement', ['an unrelated list', 'a weather tool', 'a text theme'], 'Patterns help predict what comes next.'),
      c('data', 'information collected to answer a question', ['a feeling only', 'a punctuation mark', 'a plot conflict'], 'Data can be shown in tables and graphs.'),
    ];
  }
  return [
    c('main idea', 'what a text is mostly about', ['one tiny detail', 'the final punctuation', 'a random guess'], 'The main idea is the big point.'),
    c('evidence', 'details that support an answer or claim', ['a guess with no support', 'a page color', 'an unrelated example'], 'Use evidence from the text.'),
    c('context', 'surrounding information that helps meaning', ['a number line only', 'a map scale', 'a coin value'], 'Context helps readers understand.'),
    c('structure', 'how ideas are organized', ['only the title font', 'a random word', 'a math product'], 'Structure shapes meaning.'),
    c('audience', 'the people a text or speech is meant for', ['the author only', 'a unit of length', 'a science tool'], 'Audience affects word choice and style.'),
  ];
};

const configuredNativeModes = Object.values(NATIVE_ENGLISH_GRADE_UNITS)
  .flatMap((gradeUnits) => Object.values(gradeUnits).flat())
  .map((unit) => unit.mode);

const generatedMissingUnits: Record<string, GeneralProblem[]> = Object.fromEntries(
  configuredNativeModes
    .filter((mode) => !(mode in units) && !(mode in extraUnits))
    .map((mode) => [mode, conceptUnit(mode.replace(/_/g, ' '), fallbackConceptsFor(mode))]),
);

const allUnits = {
  ...units,
  ...extraUnits,
  ...generatedMissingUnits,
};

export const NATIVE_ENGLISH_UNIT_DATA: Record<string, GeneralProblem[]> = Object.fromEntries(
  Object.entries(allUnits).map(([mode, problems]) => [mode, fillToFifty(problems)]),
);
